    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    if not test:
        return {}

    char_count = {}
    for char in test.lower():
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

